					"groups",
					() => new GroupListView(this),
					undefined,
				),
			)
		}

		if (logins.getUserController().isGlobalAdmin()) {
			adminFolders.push(
				new SettingsFolder(
					"globalSettings_label",
					() => BootIcons.Settings,
					"global",
					() => new GlobalSettingsViewer(),
					undefined,
				),
			)

			if (!logins.isEnabled(FeatureType.WhitelabelChild) && !isIOSApp()) {
				adminFolders.push(
